export function getCityByCode(code: string): TurkeyCity | undefined {
  return TURKEY_CITIES.find((c) => c.code === code);
}

export function getDistrictsForCity(cityCode: string): TurkeyDistrict[] {
  return TURKEY_DISTRICTS_BY_CITY[cityCode] ?? [];
}

export function findDistrict(cityCode: string, districtCode: string): TurkeyDistrict | undefined {
  return getDistrictsForCity(cityCode).find((d) => d.code === districtCode);
}

export function isValidCityDistrict(cityCode: string, districtCode: string): boolean {
  return !!findDistrict(cityCode, districtCode);
}
